import SwiftUI
#if canImport(UIKit)
import UIKit
#endif

/// A REAL server-rendered hole image baked in for the DESIGN SNAPSHOT so the watch hole view renders the
/// actual CourseView geometry — the fairway / putting green / water / bunkers / tree-line drawn by the
/// backend `hole_render.render_hole` (PIL) — instead of hand-drawn shapes. Source: **gid31669 hole 1**
/// (Par 4, 405 m). The overlay is 720×1120 at ppm≈1.072; the px below are the real `prep_hole` route
/// projection (tee → pin). Baking it (vs a live fetch) keeps the CI snapshot deterministic and offline.
enum WatchHoleMapSample {
    static let imageSize = CGSize(width: 720, height: 1120)
    static let ppm: CGFloat = 1.0721                      // display px per metre
    static let teePx = CGPoint(x: 349.9, y: 956.3)       // hole tee (route start)
    static let pinPx = CGPoint(x: 349.9, y: 522.1)       // green centre / pin (route end)
    /// Representative "you": a fairway lie ~150 m out — the you-centred, green-ahead layout the design shows.
    static let youPx = CGPoint(x: 347, y: 683)

    #if canImport(UIKit)
    static let image: UIImage? = Data(base64Encoded: jpegBase64).flatMap(UIImage.init(data:))
    #endif

    static let jpegBase64 = ""
}
